<?php
// Renderiza una factura persistida, sin ejecutar SQL generado por IA.
$bd = new SQLite3(__DIR__.'/empresa.db', SQLITE3_OPEN_READONLY);
$bd->enableExceptions(true);
$id = filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);
if (!$id || $id < 1) { http_response_code(400); exit('Factura no válida'); }
$q=$bd->prepare('SELECT f.id AS factura_id,f.numero,f.fecha AS factura_fecha,f.base,f.iva,f.total,f.pedido_id,f.cliente_nombre,f.cliente_apellidos,f.cliente_email,f.cliente_telefono,f.cliente_ciudad,f.producto_nombre,f.producto_modelo,f.producto_categoria,f.producto_potencia,f.producto_autonomia FROM facturas f WHERE f.id=:id');
$q->bindValue(':id',$id,SQLITE3_INTEGER);
$d=$q->execute()->fetchArray(SQLITE3_ASSOC);
if (!$d) {http_response_code(404);exit('Factura no encontrada');}
function h($v){return htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function eur($v){return number_format((float)$v,2,',','.').' €';}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Factura <?=h($d['numero'])?></title><style>*{box-sizing:border-box}body{margin:0;padding:35px;background:#e8edf2;font-family:Arial,sans-serif;color:#333}.factura{max-width:800px;margin:auto;padding:45px;background:white;box-shadow:0 5px 25px #0002}header,.datos{display:flex;justify-content:space-between;gap:30px}header{border-bottom:3px solid steelblue;padding-bottom:25px}h1{margin:0;color:steelblue;font-size:36px}h2{font-size:17px;color:steelblue}p{line-height:1.7;margin:4px 0}.datos{margin:35px 0}.datos>div{flex:1}table{width:100%;border-collapse:collapse;margin-top:25px}th{background:steelblue;color:white;text-align:left}th,td{padding:14px;border-bottom:1px solid #ddd}.numero{text-align:right}.totales{width:300px;max-width:100%;margin:30px 0 30px auto}.totales p{display:flex;justify-content:space-between;padding:8px 0}.total{font-size:22px;font-weight:bold;color:steelblue;border-top:2px solid steelblue}footer{margin-top:60px;border-top:1px solid #ddd;padding-top:20px;text-align:center;color:#777;font-size:13px}.acciones{text-align:center;margin:25px}button{background:steelblue;color:white;padding:14px 30px;border:0;border-radius:6px;cursor:pointer}@page{size:A4;margin:15mm}@media print{body{padding:0;background:white}.factura{max-width:none;padding:0;box-shadow:none}.acciones{display:none}th{print-color-adjust:exact;-webkit-print-color-adjust:exact}}</style></head><body><div class="factura"><header><div><h1>FACTURA</h1><p>Nº <?=h($d['numero'])?></p><p>Fecha: <?=h($d['factura_fecha'])?></p><p>Pedido: <?=h($d['pedido_id'] ?: 'Sin pedido')?></p></div><div><h2>JOCARSA</h2><p>Complete aquí los datos fiscales reales del emisor</p></div></header><section class="datos"><div><h2>Emisor</h2><p>JOCARSA</p><p>Datos fiscales pendientes de configurar</p></div><div><h2>Receptor</h2><p><strong><?=h($d['cliente_nombre'].' '.$d['cliente_apellidos'])?></strong></p><p><?=h($d['cliente_ciudad'])?></p><p><?=h($d['cliente_email'])?></p><p><?=h($d['cliente_telefono'])?></p></div></section><h2>Detalle</h2><table><thead><tr><th>Producto</th><th>Modelo</th><th class="numero">Cantidad</th><th class="numero">Importe</th></tr></thead><tbody><tr><td><?=h($d['producto_nombre'])?></td><td><?=h($d['producto_modelo'])?></td><td class="numero">1</td><td class="numero"><?=eur($d['base'])?></td></tr></tbody></table><section><h2>Características del vehículo</h2><p>Categoría: <?=h($d['producto_categoria'])?></p><p>Potencia: <?=h($d['producto_potencia'])?> CV</p><p>Autonomía: <?=h($d['producto_autonomia'])?> km</p></section><div class="totales"><p><span>Base imponible</span><span><?=eur($d['base'])?></span></p><p><span>IVA (21%)</span><span><?=eur($d['iva'])?></span></p><p class="total"><span>TOTAL</span><span><?=eur($d['total'])?></span></p></div><footer>Factura generada electrónicamente.</footer></div><div class="acciones"><button onclick="window.print()">Imprimir / Guardar PDF</button></div></body></html>
